    "quote": "“Families like ours need SEND reform to remain a genuine priority for the new Prime Minister and Government. Too often, families are left to navigate complicated systems, repeatedly chase support and fight for services that should already be available. The transition from childhood into adulthood is particularly difficult. Education, health and social care do not always work together, and planning often begins too late for young people who need considerable preparation and consistency.”",
