    "quote": "“We had to fight via Tribunal to get our daughter the supporting therapies her EHCP already said she was entitled to. Our son never got any supporting therapies, including the Sensory Occupational Therapy assessment that was written in his EHCP for 4 years (before he aged out at 16). This is so deeply wrong: these children are entitled to good, effective health care, especially when it is mandated in their EHCPs. We should not have to have yet another fight with the system just to access health care.”",
