    "appeal_rate_2025": "0.9",
    "quote": "“Access to proper, timely health support is the foundation of everything for us, because without it, every other part of life becomes harder to manage. We navigate lifelong complex health needs, a serious accident at school causing permanent new injury, and long waits for major surgery. On top of that, we've faced education failures, SEND disputes, appeals over essential transport to further education, plus repeated gaps, delays and refusals across social care, occupational therapy, housing adaptations and essential support services.”",
    "parent_location": "North East England",
    "4months_pct": "18.0%"
